"""Gitignored, generated and minified files stay out of the graph.

Built by the real builder over real (tiny) git repos, like
test_js_kotlin_calls.py. One test per scenario in
openspec/changes/2026-10-23-code-graph-index-scope/specs/code-graph/spec.md.

Run:  python -m unittest discover .github/code-graph/tests
"""
from __future__ import annotations

import shutil
import sqlite3
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path
from unittest import mock

CODE_GRAPH = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(CODE_GRAPH))

import builder  # noqa: E402

needs_git = unittest.skipIf(shutil.which("git") is None, "git not on PATH")


MINIFIED_CSS = ".a{color:red}" * 800  # one 10 KB line

# Root is not a git repo; web/ and api/ are.
WORKSPACE = {
    "web/.gitignore": "public/\ngenerated/\n*.local.py\n",
    "web/src/app.ts": "export function render() {\n  return 1;\n}\n",
    "web/src/new.py": "def fresh():\n    return 1\n",
    "web/src/secret.local.py": "def secret():\n    return 1\n",
    "web/public/~partytown/lib.js": "function partytown() {\n  return 1;\n}\n",
    "web/generated/types.ts": "export function generatedType() {\n  return 1;\n}\n",
    "web/src/api/client.ts": (
        "/* This file was auto-generated by openapi-typescript. "
        "Do not make direct changes. */\n"
        "export function getUsers() {\n  return [];\n}\n"
    ),
    "web/src/token.ts": (
        "/* eslint-disable */\n"
        "// the token is generated by the server\n"
        "export function readToken() {\n  return '';\n}\n"
    ),
    "web/static/site.css": MINIFIED_CSS + "\n",
    "web/static/theme.min.css": ".b{color:blue}\n",
    "web/static/plain.css": ".c {\n  color: green;\n}\n",
    "api/handler.py": "def handle():\n    return 1\n",
    "api/generated/keep.py": "def kept():\n    return 1\n",
    "api/pb/user.pb.go": (
        "// Code generated by protoc-gen-go. DO NOT EDIT.\n"
        "package pb\n\nfunc Marshal() {}\n"
    ),
}


def _write(root: Path, files: dict[str, str]) -> None:
    for rel, body in files.items():
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(body, encoding="utf-8")


def _git_init(repo: Path) -> None:
    subprocess.run(["git", "init", "-q", str(repo)], check=True)


def _git(repo: Path, *args: str) -> None:
    subprocess.run(["git", "-C", str(repo), "-c", "user.name=t",
                    "-c", "user.email=t@t", *args], check=True, capture_output=True)


class _GraphCase(unittest.TestCase):
    conn: sqlite3.Connection

    def files(self) -> set[str]:
        return {f for (f,) in self.conn.execute("SELECT DISTINCT file FROM nodes")}


@needs_git
class MultiRepoScopeTests(_GraphCase):
    tmp: Path

    @classmethod
    def setUpClass(cls) -> None:
        cls.tmp = Path(tempfile.mkdtemp(prefix="coograph-scope-"))
        _write(cls.tmp, WORKSPACE)
        _git_init(cls.tmp / "web")
        _git_init(cls.tmp / "api")
        with unittest.TestCase().assertLogs("code-graph.builder", level="INFO") as cls.logs:
            db = builder.build(cls.tmp)
        cls.conn = sqlite3.connect(db)

    @classmethod
    def tearDownClass(cls) -> None:
        cls.conn.close()
        shutil.rmtree(cls.tmp, ignore_errors=True)

    def log_text(self) -> str:
        return "\n".join(self.logs.output)

    # -- gitignore -----------------------------------------------------------

    def test_gitignored_build_output_is_not_indexed(self):
        files = self.files()
        self.assertIn("web/src/app.ts", files)
        self.assertFalse([f for f in files if f.startswith("web/public/")])

    def test_gitignored_file_is_not_indexed(self):
        files = self.files()
        self.assertNotIn("web/src/secret.local.py", files)
        self.assertIn("web/src/new.py", files)

    def test_child_repo_ignores_apply_under_a_non_git_root(self):
        files = self.files()
        self.assertFalse([f for f in files if f.startswith("web/generated/")])
        self.assertIn("api/handler.py", files)

    def test_one_repos_ignores_do_not_leak_into_another(self):
        self.assertIn("api/generated/keep.py", self.files())

    def test_untracked_but_not_ignored_file_is_indexed(self):
        self.assertIn("web/src/new.py", self.files())

    # -- generated -----------------------------------------------------------

    def test_generated_api_client_is_skipped(self):
        self.assertNotIn("web/src/api/client.ts", self.files())
        self.assertRegex(self.log_text(), r"\b2 generated\b")

    def test_go_generated_marker_is_skipped(self):
        self.assertNotIn("api/pb/user.pb.go", self.files())

    def test_hand_written_file_mentioning_generation_is_kept(self):
        self.assertIn("web/src/token.ts", self.files())

    # -- minified CSS --------------------------------------------------------

    def test_minified_css_is_skipped(self):
        files = self.files()
        self.assertNotIn("web/static/site.css", files)
        self.assertNotIn("web/static/theme.min.css", files)
        self.assertIn("web/static/plain.css", files)
        self.assertRegex(self.log_text(), r"Skipped 2 minified\b")

    def test_gitignored_paths_are_counted(self):
        self.assertRegex(self.log_text(), r"3 gitignored path\(s\) in 2 repo\(s\)")


class GeneratedMarkerTests(unittest.TestCase):
    def check(self, head: str) -> bool:
        tmp = Path(tempfile.mkdtemp(prefix="coograph-gen-"))
        try:
            path = tmp / "f.ts"
            path.write_text(head + "\nexport const x = 1;\n", encoding="utf-8")
            return builder._is_generated(path)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_markers(self):
        for head in ("// @generated", "/* autogenerated */",
                     "# This file is automatically generated",
                     "// Code generated by sqlc. DO NOT EDIT.",
                     "// generated file, do not modify",
                     " * NOTE: This class is auto generated by OpenAPI Generator",
                     "/**\n * Generated by orval v6.31.0\n * Do not edit manually.\n */"):
            with self.subTest(head=head):
                self.assertTrue(self.check(head))

    def test_not_markers(self):
        for head in ("/* eslint-disable */", "// ids are generated on save",
                     "// do not edit this by hand",
                     "# Generated by Django 4.2.7 on 2024-01-01 10:00",
                     "   generated by hand, see notes"):
            with self.subTest(head=head):
                self.assertFalse(self.check(head))

    def test_marker_after_ten_lines_is_ignored(self):
        self.assertFalse(self.check("\n" * 10 + "// @generated"))


@needs_git
class SingleRepoScopeTests(_GraphCase):
    """Root is itself a git repo; update() drops a newly ignored folder."""

    def setUp(self) -> None:
        self.tmp = Path(tempfile.mkdtemp(prefix="coograph-repo-"))
        _write(self.tmp, {
            ".gitignore": "public/\n",
            "src/app.py": "def main():\n    return 1\n",
            "public/bundle.py": "def bundled():\n    return 1\n",
            "out2/bundle.py": "def later():\n    return 1\n",
        })
        _git_init(self.tmp)

    def tearDown(self) -> None:
        if getattr(self, "conn", None) is not None:
            self.conn.close()
        shutil.rmtree(self.tmp, ignore_errors=True)

    def test_root_repo_ignores_apply(self):
        self.conn = sqlite3.connect(builder.build(self.tmp))
        files = self.files()
        self.assertIn("src/app.py", files)
        self.assertNotIn("public/bundle.py", files)

    def test_update_drops_a_newly_ignored_folder(self):
        db = builder.build(self.tmp)
        self.conn = sqlite3.connect(db)
        self.assertIn("out2/bundle.py", self.files())
        self.conn.close()
        (self.tmp / ".gitignore").write_text("public/\nout2/\n", encoding="utf-8")
        builder.update(self.tmp)
        self.conn = sqlite3.connect(db)
        self.assertNotIn("out2/bundle.py", self.files())
        self.assertIn("src/app.py", self.files())

    def test_update_drops_a_file_that_becomes_generated(self):
        db = builder.build(self.tmp)
        (self.tmp / "src/app.py").write_text(
            "# @generated by a tool\ndef main():\n    return 1\n", encoding="utf-8")
        builder.update(self.tmp)
        self.conn = sqlite3.connect(db)
        self.assertNotIn("src/app.py", self.files())

    def test_git_unavailable_indexes_as_before(self):
        failures = (FileNotFoundError("git"),
                    subprocess.TimeoutExpired("git", 30),
                    subprocess.CalledProcessError(128, "git"))
        for failure in failures:
            with self.subTest(failure=type(failure).__name__), \
                 mock.patch.object(builder.subprocess, "run", side_effect=failure), \
                 self.assertLogs("code-graph.builder", level="WARNING") as logs:
                self.conn = sqlite3.connect(builder.build(self.tmp))
                self.assertIn("public/bundle.py", self.files())
                self.conn.close()
                self.conn = None
            self.assertEqual(1, sum("git" in line for line in logs.output))


@needs_git
class HookEnvironmentTests(_GraphCase):
    """A post-commit hook exports a relative GIT_INDEX_FILE; a linked worktree
    (a `.git` file) under the root must still read its own index."""

    def setUp(self) -> None:
        self.tmp = Path(tempfile.mkdtemp(prefix="coograph-hook-"))
        main = self.tmp / "main"
        _write(main, {".gitignore": "gen.py\n",
                      "gen.py": "def tracked():\n    return 1\n"})
        _git_init(main)
        _git(main, "add", "-f", ".gitignore", "gen.py")
        _git(main, "commit", "-q", "-m", "init")
        _git(main, "worktree", "add", "-q", str(self.tmp / "wt"))

    def tearDown(self) -> None:
        if getattr(self, "conn", None) is not None:
            self.conn.close()
        shutil.rmtree(self.tmp, ignore_errors=True)

    def test_tracked_file_matching_an_ignore_stays_indexed(self):
        with mock.patch.dict(builder.os.environ, {"GIT_INDEX_FILE": ".git/index"}):
            self.conn = sqlite3.connect(builder.build(self.tmp))
        files = self.files()
        self.assertIn("main/gen.py", files)
        self.assertIn("wt/gen.py", files)


if __name__ == "__main__":
    unittest.main()
